def max_probability(n, p):
    # Calculate the probability of getting exactly one problem
    def prob_of_one_problem(subset):
        prob = 1.0
        for i in range(n):
            if i in subset:
                prob *= p[i]
            else:
                prob *= (1 - p[i])
        return prob

    max_prob = 0.0
    # Iterate over all possible subsets of friends
    for r in range(1, n + 1):
        for subset in combinations(range(n), r):
            # Calculate the probability of getting exactly one problem from this subset
            prob = prob_of_one_problem(subset)
            # Check if this subset gives a higher probability
            if prob > max_prob:
                max_prob = prob

    return max_prob

